local CompostSieveMaker = {}
local PRODUCTS = {
    iron_compostsieve = { name = "Železni sitana za kompost", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni sitana za kompost za vrtnarje." },
    bronze_compostsieve = { name = "Bronast sitana za kompost", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast sitana za kompost za vrtnarje." },
    silver_compostsieve = { name = "Srebrn sitana za kompost", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn sitana za kompost za vrtnarje." },
    gilded_compostsieve = { name = "Pozlačen sitana za kompost", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen sitana za kompost za vrtnarje." },
    jewel_set_compostsieve = { name = "Draguljast sitana za kompost", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast sitana za kompost za vrtnarje." },
    royal_sovereign_compostsieve = { name = "Kraljevski suveren sitana za kompost", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren sitana za kompost z biseri za krono." },
}
local BUILDINGS = {
    compostsieve_workshop = { name = "Compostsieve delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    compostsieve_house = { name = "Compostsieve hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_compostsieve_atelier = { name = "Mojstrski compostsieve atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_compostsieve_palace = { name = "Suverena compostsieve palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
CompostSieveMaker.ironStock=12; CompostSieveMaker.bronzeStock=10; CompostSieveMaker.woodStock=16; CompostSieveMaker.leatherStock=10; CompostSieveMaker.silverStock=8; CompostSieveMaker.goldStock=6; CompostSieveMaker.jewelStock=4; CompostSieveMaker.pearlStock=4
CompostSieveMaker.productStock = {}; CompostSieveMaker.buildings = {}; CompostSieveMaker.maker = nil; CompostSieveMaker.activeMaking = {}; CompostSieveMaker.totalProducts = 0; CompostSieveMaker.dayTimer = 0
function CompostSieveMaker.init() CompostSieveMaker.ironStock=12; CompostSieveMaker.bronzeStock=10; CompostSieveMaker.woodStock=16; CompostSieveMaker.leatherStock=10; CompostSieveMaker.silverStock=8; CompostSieveMaker.goldStock=6; CompostSieveMaker.jewelStock=4; CompostSieveMaker.pearlStock=4; CompostSieveMaker.productStock={}; CompostSieveMaker.buildings={}; CompostSieveMaker.maker=nil; CompostSieveMaker.activeMaking={}; CompostSieveMaker.totalProducts=0; CompostSieveMaker.dayTimer=0; print("[CompostSieveMaker] Royal Compost Sieve Maker System initialized (6 products, 4 buildings)") end
function CompostSieveMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CompostSieveMaker.maker={name=n or ("Sitnikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sitnikar najet: %s (spretnost: %d)",CompostSieveMaker.maker.name,s),"success") end; return true end
function CompostSieveMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CompostSieveMaker.build(id) local ok,e=CompostSieveMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CompostSieveMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CompostSieveMaker.getQualityBonus() local b=0; for _,bd in ipairs(CompostSieveMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CompostSieveMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CompostSieveMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CompostSieveMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CompostSieveMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CompostSieveMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CompostSieveMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CompostSieveMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CompostSieveMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CompostSieveMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CompostSieveMaker.buildings==0 then return false,"Potrebna sitnična delavnica" end; if not CompostSieveMaker.maker then return false,"Potreben sitnikar" end; return true end
function CompostSieveMaker.make(pt,qty) qty=qty or 1; local ok,e=CompostSieveMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CompostSieveMaker.ironStock=CompostSieveMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CompostSieveMaker.bronzeStock=CompostSieveMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CompostSieveMaker.woodStock=CompostSieveMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CompostSieveMaker.leatherStock=CompostSieveMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CompostSieveMaker.silverStock=CompostSieveMaker.silverStock-d.silverCost*qty end; if d.goldCost then CompostSieveMaker.goldStock=CompostSieveMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CompostSieveMaker.jewelStock=CompostSieveMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CompostSieveMaker.pearlStock=CompostSieveMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CompostSieveMaker.maker then t=math.max(1,t-math.floor(CompostSieveMaker.maker.skill/13)) end; table.insert(CompostSieveMaker.activeMaking,{id="compostsieve_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CompostSieveMaker.completeMaking(m) local q=1.0+(CompostSieveMaker.getQualityBonus()/100); if CompostSieveMaker.maker then q=q+(CompostSieveMaker.maker.skill/140) end; q=math.min(2.5,q); CompostSieveMaker.productStock[m.productType]=(CompostSieveMaker.productStock[m.productType] or 0)+m.quantity; CompostSieveMaker.totalProducts=CompostSieveMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CompostSieveMaker.maker then CompostSieveMaker.maker.itemsMade=CompostSieveMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CompostSieveMaker.maker.skill=math.min(100,CompostSieveMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sito izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"compostsieve.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CompostSieveMaker.update(dt) if not _G.state then return end; CompostSieveMaker.dayTimer=CompostSieveMaker.dayTimer+dt; if CompostSieveMaker.dayTimer>=30 then CompostSieveMaker.dayTimer=0; for i=#CompostSieveMaker.activeMaking,1,-1 do local m=CompostSieveMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CompostSieveMaker.completeMaking(m); table.remove(CompostSieveMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CompostSieveMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CompostSieveMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CompostSieveMaker.getStats() return {ironStock=CompostSieveMaker.ironStock,bronzeStock=CompostSieveMaker.bronzeStock,woodStock=CompostSieveMaker.woodStock,leatherStock=CompostSieveMaker.leatherStock,silverStock=CompostSieveMaker.silverStock,goldStock=CompostSieveMaker.goldStock,jewelStock=CompostSieveMaker.jewelStock,pearlStock=CompostSieveMaker.pearlStock,productStock=CompostSieveMaker.productStock,numBuildings=#CompostSieveMaker.buildings,hasMaker=CompostSieveMaker.maker~=nil,makerName=CompostSieveMaker.maker and CompostSieveMaker.maker.name or "—",makerSkill=CompostSieveMaker.maker and CompostSieveMaker.maker.skill or 0,activeMaking=#CompostSieveMaker.activeMaking,totalProducts=CompostSieveMaker.totalProducts} end
return CompostSieveMaker
